# Compute layer-depth maps for test connected components (wall 9), print clues by layer
from collections import defaultdict, deque
compsT=comps_by_wall(G,9)
def component_depths(M, cells, wall):
    s=set(cells); dist={}; q=deque()
    R,C=len(M),len(M[0])
    for r,c in cells:
        if (r==0 or c==0 or r==R-1 or c==C-1 or any((r+dr,c+dc) not in s for dr,dc in ((-1,0),(1,0),(0,-1),(0,1)))):
            dist[(r,c)]=0;q.append((r,c))
    while q:
        r,c=q.popleft()
        for dr,dc in ((-1,0),(1,0),(0,-1),(0,1)):
            p=(r+dr,c+dc)
            if p in s and p not in dist:
                dist[p]=dist[(r,c)]+1;q.append(p)
    return dist
for ix,cells in enumerate(compsT):
