def fill_layers(M, wall, bg):
    out=[row[:] for row in M]
    infos=[]
    for cells in comps_by_wall(M,wall):
        dist=component_depths(M,cells,wall)
        bydepth=defaultdict(list)
        for p in cells:
            r,c=p
            if M[r][c] != bg:
                bydepth[dist[p]].append(M[r][c])
        # derive palette from the non-background seed(s), including bg as layer 0 if absent
        maxd=max(bydepth) if bydepth else 0
        pal=[]
        for d in range(maxd+1):
            vals=bydepth.get(d,[])
            if vals:
                # expected unique color per seed layer
                pal.append(Counter(vals).most_common(1)[0][0])
            elif d==0:
                pal.append(bg)
            else:
                # fallback: use background for a missing palette layer
                pal.append(bg)
        if not pal: pal=[bg]
        for p in cells:
            out[p[0]][p[1]]=pal[dist[p]%len(pal)]
        infos.append((cells,dist,pal,bydepth))
    return out,infos
